/* math module */
int64_t math__abs(int64_t x)                    { return x < 0 ? -x : x; }
int64_t math__max(int64_t a, int64_t b)         { return a > b ? a : b; }
int64_t math__min(int64_t a, int64_t b)         { return a < b ? a : b; }
int64_t math__clamp(int64_t v, int64_t lo, int64_t hi) {
    if (v < lo) return lo; if (v > hi) return hi; return v;
}
int64_t math__pow(int64_t base, int64_t exp) {
    int64_t r = 1;
    for (int64_t i = 0; i < exp; i++) r *= base;
    return r;
}
double  math__sqrt(double x)   { return sqrt(x); }
int64_t math__floor(double x)  { return (int64_t)floor(x); }
int64_t math__ceil(double x)   { return (int64_t)ceil(x); }
