/* strings module */
char* strings__repeat(const char* s, int64_t n) {
    if (!s || n <= 0) return strdup("");
    size_t slen = strlen(s);
    size_t total = (size_t)n * slen;
    char* r = (char*)malloc(total + 1);
    for (int64_t i = 0; i < n; i++) memcpy(r + (size_t)i * slen, s, slen);
    r[total] = '\0';
    return r;
}
int64_t strings__count(const char* s, const char* sub) {
    if (!s || !sub || sub[0] == '\0') return 0;
    int64_t count = 0;
    size_t sublen = strlen(sub);
    const char* cur = s;
    while ((cur = strstr(cur, sub)) != NULL) { count++; cur += sublen; }
    return count;
}
char* strings__join(void* arr, const char* sep) {
    if (!arr) return strdup("");
    HakiArray* a = (HakiArray*)arr;
    int64_t len = haki_array_length(a);
    if (len == 0) return strdup("");
    size_t seplen = sep ? strlen(sep) : 0;
    size_t total = 0;
    for (int64_t i = 0; i < len; i++) {
        const char* s = *(const char**)haki_array_get(a, i);
        if (s) total += strlen(s);
        if (i < len - 1) total += seplen;
    }
    char* result = (char*)malloc(total + 1);
    size_t pos = 0;
    for (int64_t i = 0; i < len; i++) {
        const char* s = *(const char**)haki_array_get(a, i);
        if (s) { size_t sl = strlen(s); memcpy(result + pos, s, sl); pos += sl; }
        if (i < len - 1 && sep) { memcpy(result + pos, sep, seplen); pos += seplen; }
    }
    result[pos] = '\0';
    return result;
}
char* strings__toUpper(const char* s) { return haki_string_to_upper(s); }
char* strings__toLower(const char* s) { return haki_string_to_lower(s); }
int64_t strings__length(const char* s) { return haki_string_length(s); }

/* fs module */
char*   fs__read(const char* path) {
    /* haki_read_file returns a (string, Error?) tuple — extract just the string */
    void** t = (void**)haki_read_file(path);
    return t ? (char*)t[0] : (char*)"";
}
void*   fs__write(const char* path, const char* c)   { return haki_write_file(path, c); }
int8_t  fs__exists(const char* path)                 { return haki_file_exists(path); }
void*   fs__delete(const char* path) {
    if (!path) return NULL;
    remove(path);
    rmdir(path);
    return NULL;
}
void*   fs__mkdir(const char* path) {
#ifdef _WIN32
    _mkdir(path);
#else
    mkdir(path, 0755);
#endif
    return NULL;
}
void*   fs__readDir(const char* path) {
    void* arr = haki_array_new(sizeof(void*));
#ifndef _WIN32
    DIR* d = opendir(path);
    if (!d) return arr;
    struct dirent* entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        char* name = strdup(entry->d_name);
        haki_array_append(arr, &name);
    }
    closedir(d);
#endif
    return arr;
}

/* env module */
/* env__get: return the string value or NULL (not the (string, Error?) tuple) */
const char* env__get(const char* name) {
    const char* val = getenv(name);
    return val ? strdup(val) : NULL;
}
void*   env__set(const char* name, const char* val)  { return haki_env_set(name, val); }
void*   env__unset(const char* name)                 { return haki_env_unset(name); }
void*   env__cwd(void)                               { return haki_env_cwd(); }

/* process module */
void*   process__args(void)                          { return haki_process_args(); }
void    process__exit(int64_t code)                  { haki_process_exit(code); }
int64_t process__pid(void)                           { return haki_getpid(); }
